import{_ as t,o as h,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Xử lý bốn nhánh của cơ thể thay thế bóng tối","description":"","frontmatter":{},"headers":[],"relativePath":"vi/0059-黑暗置换体四类分支处置.md","filePath":"vi/0059-黑暗置换体四类分支处置.md"}'),g={name:"vi/0059-黑暗置换体四类分支处置.md"};function a(u,n,o,d,l,r){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="xu-ly-bon-nhanh-cua-co-the-thay-the-bong-toi" tabindex="-1">Xử lý bốn nhánh của cơ thể thay thế bóng tối <a class="header-anchor" href="#xu-ly-bon-nhanh-cua-co-the-thay-the-bong-toi" aria-label="Permalink to &quot;Xử lý bốn nhánh của cơ thể thay thế bóng tối&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>59</td></tr><tr><td>Mô-đun</td><td>Chủng tộc và hình thái sự sống</td></tr><tr><td>Từ khóa cốt lõi</td><td>Hợp nhất cộng sinh, tách đặt, phong ấn giám sát, tiêu hủy, xử lý theo nhánh</td></tr></tbody></table><h2 id="_1-cau-truc-tong-the-cua-xu-ly-theo-nhanh" tabindex="-1">1. Cấu trúc tổng thể của xử lý theo nhánh <a class="header-anchor" href="#_1-cau-truc-tong-the-cua-xu-ly-theo-nhanh" aria-label="Permalink to &quot;1. Cấu trúc tổng thể của xử lý theo nhánh&quot;">​</a></h2><p>Xử lý cơ thể thay thế bóng tối là lĩnh vực phức tạp nhất trong quản trị sự sống của văn minh cộng sinh neo. Khác với quy trình xử lý ba loại sự sống kỳ lạ và năng lượng kỳ lạ, cơ thể thay thế bóng tối do liên quan đến cấu trúc đặc biệt của đồng tồn tại linh hồn song sinh (xem chi tiết &quot;57-Nguồn gốc và bản chất của cơ thể thay thế bóng tối&quot;), đòi hỏi kế hoạch xử lý theo nhánh tinh vi hơn. Dựa trên các nguyên tắc đạo đức được thiết lập bởi &quot;58-Nguyên tắc đạo đức linh hồn song sinh&quot;, kết hợp với giai đoạn phát triển của cơ thể thay thế bóng tối, trạng thái linh hồn của vật chủ ban đầu, đặc điểm của linh hồn bóng tối và mức độ rủi ro, xử lý cơ thể thay thế bóng tối được chia thành bốn nhánh: loại hợp nhất cộng sinh, loại tách đặt, loại phong ấn giám sát, loại tiêu hủy.</p><p>Việc lựa chọn xử lý bốn nhánh tuân theo logic ra quyết định sau:</p><table tabindex="0"><thead><tr><th>Yếu tố ra quyết định</th><th>Điểm cân nhắc</th></tr></thead><tbody><tr><td>Giai đoạn phát triển</td><td>Từ giai đoạn một đến ba ưu tiên cứu rỗi, giai đoạn bốn đánh giá thận trọng, giai đoạn năm vật chủ ban đầu đã chết</td></tr><tr><td>Trạng thái linh hồn vật chủ ban đầu</td><td>Linh hồn vật chủ ban đầu còn tồn tại không, có thể biểu đạt ý chí không, có khả năng phục hồi không</td></tr><tr><td>Đặc điểm linh hồn bóng tối</td><td>Linh hồn bóng tối có khả năng giao tiếp không, có không gian cải tạo không, mức độ phá hủy</td></tr><tr><td>Mức độ rủi ro</td><td>Mức độ đe dọa đối với an toàn công cộng và quyền lợi của người khác</td></tr><tr><td>Kết luận xét duyệt đạo đức</td><td>Ý kiến xét duyệt và quyết định của ủy ban xét duyệt đạo đức linh hồn song sinh</td></tr><tr><td>Ý chí vật chủ ban đầu</td><td>Sự lựa chọn của linh hồn vật chủ ban đầu trong trạng thái có thể biểu đạt ý chí</td></tr></tbody></table><h2 id="_2-loai-thu-nhat-xu-ly-loai-hop-nhat-cong-sinh" tabindex="-1">2. Loại thứ nhất: Xử lý loại hợp nhất cộng sinh <a class="header-anchor" href="#_2-loai-thu-nhat-xu-ly-loai-hop-nhat-cong-sinh" aria-label="Permalink to &quot;2. Loại thứ nhất: Xử lý loại hợp nhất cộng sinh&quot;">​</a></h2><p>Xử lý loại hợp nhất cộng sinh là phương pháp xử lý tích cực và mang tính xây dựng nhất trong bốn nhánh, áp dụng cho các cơ thể thay thế bóng tối mà linh hồn vật chủ ban đầu và linh hồn bóng tối có khả năng đạt được hòa giải và thực hiện hợp nhất linh hồn.</p><h3 id="_1-đieu-kien-ap-dung" tabindex="-1">(1) Điều kiện áp dụng <a class="header-anchor" href="#_1-đieu-kien-ap-dung" aria-label="Permalink to &quot;(1) Điều kiện áp dụng&quot;">​</a></h3><p>Xử lý loại hợp nhất cộng sinh phải đồng thời đáp ứng các điều kiện sau:</p><ol><li>Cơ thể thay thế bóng tối đang ở giai đoạn ba (giai đoạn hình thành linh hồn song sinh) hoặc đầu giai đoạn bốn (đầu giai đoạn thống trị bóng tối), linh hồn vật chủ ban đầu vẫn tồn tại và có ý thức tự chủ nhất định.</li><li>Linh hồn vật chủ ban đầu đã rõ ràng biểu đạt ý chí muốn thử hợp nhất với linh hồn bóng tối, và ý chí đó được công nhận là chân thực và tự chủ.</li><li>Linh hồn bóng tối có khả năng giao tiếp nhất định, thể hiện đặc điểm không thuần túy phá hủy, có khả năng chấp nhận hợp nhất.</li><li>Đánh giá mức độ rủi ro là cấp hai (rủi ro trung bình) trở xuống, quá trình hợp nhất sẽ không cấu thành đe dọa không kiểm soát được đối với an toàn công cộng.</li><li>Được ủy ban xét duyệt đạo đức linh hồn song sinh phê duyệt.</li></ol><h3 id="_2-muc-tieu-xu-ly" tabindex="-1">(2) Mục tiêu xử lý <a class="header-anchor" href="#_2-muc-tieu-xu-ly" aria-label="Permalink to &quot;(2) Mục tiêu xử lý&quot;">​</a></h3><p>Thông qua hướng dẫn linh hồn vật chủ ban đầu và linh hồn bóng tối đạt được hòa giải, thực hiện hợp nhất hữu cơ của hai linh hồn, hình thành một linh hồn mới kết hợp ký ức, nhân cách của vật chủ ban đầu và sức mạnh bóng tối. Linh hồn mới sau hợp nhất giữ lại danh tính công dân và quyền lợi hợp pháp của vật chủ ban đầu, đồng thời có được khả năng kiểm soát năng lượng bóng tối, trở thành thành viên đặc biệt của văn minh cộng sinh.</p><h3 id="_3-cac-buoc-xu-ly" tabindex="-1">(3) Các bước xử lý <a class="header-anchor" href="#_3-cac-buoc-xu-ly" aria-label="Permalink to &quot;(3) Các bước xử lý&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bước</th><th>Tên</th><th>Nội dung cụ thể</th><th>Cơ quan chịu trách nhiệm</th></tr></thead><tbody><tr><td>Bước một</td><td>Xét duyệt đạo đức</td><td>Ủy ban xét duyệt đạo đức linh hồn song sinh thực hiện xét duyệt toàn diện đối với kế hoạch hợp nhất, xác nhận phù hợp với nguyên tắc đạo đức</td><td>Ủy ban xét duyệt đạo đức linh hồn song sinh</td></tr><tr><td>Bước hai</td><td>Hướng dẫn giao tiếp</td><td>Trong môi trường được kiểm soát, người hướng dẫn linh hồn chuyên nghiệp hỗ trợ linh hồn vật chủ ban đầu và linh hồn bóng tối giao tiếp, thúc đẩy hiểu biết lẫn nhau</td><td>Trung tâm điều trị linh hồn + người tu luyện</td></tr><tr><td>Bước ba</td><td>Đàm phán hòa giải</td><td>Hướng dẫn hai linh hồn đạt được thỏa thuận hòa giải về danh tính, ký ức, năng lực, quy tắc hành vi, v.v. sau hợp nhất</td><td>Trung tâm điều trị linh hồn + cố vấn pháp lý</td></tr><tr><td>Bước bốn</td><td>Chuẩn bị hợp nhất</td><td>Thực hiện các công việc chuẩn bị trước hợp nhất như điều dưỡng cơ thể, cân bằng năng lượng, xây dựng tâm lý, v.v.</td><td>Đội ngũ y tế + người hướng dẫn tu luyện</td></tr><tr><td>Bước năm</td><td>Hợp nhất linh hồn</td><td>Với sự hỗ trợ chung của người tu luyện cấp cao và nhà trị liệu linh hồn, thực hiện phẫu thuật/nghi thức hợp nhất linh hồn</td><td>Người tu luyện cấp cao + nhà trị liệu linh hồn</td></tr><tr><td>Bước sáu</td><td>Ổn định sau hợp nhất</td><td>Thực hiện điều trị ổn định đối với linh hồn mới sau hợp nhất, giám sát tính toàn vẹn của linh hồn và khả năng thích ứng của cơ thể</td><td>Đội ngũ y tế + đội ngũ giám sát</td></tr><tr><td>Bước bảy</td><td>Xác nhận danh tính</td><td>Xác nhận danh tính của linh hồn mới sau hợp nhất, giữ lại danh tính công dân của vật chủ ban đầu, cập nhật hồ sơ danh tính</td><td>Cơ quan quản lý đăng ký + Cục quản lý sự sống</td></tr><tr><td>Bước tám</td><td>Hỗ trợ hội nhập</td><td>Cung cấp các dịch vụ hỗ trợ như tư vấn tâm lý, hướng dẫn tu luyện, hội nhập xã hội, v.v. cho cá nhân sau hợp nhất</td><td>Bộ phận sự việc vạn tộc + cộng đồng</td></tr><tr><td>Bước chín</td><td>Giám sát dài hạn</td><td>Thực hiện giám sát theo dõi dài hạn không dưới 5 năm đối với cá nhân đã hợp nhất, đánh giá sự ổn định của hợp nhất và khả năng thích ứng xã hội</td><td>Cục quản lý sự sống + cộng đồng</td></tr></tbody></table><h3 id="_4-quan-ly-sau-hop-nhat" tabindex="-1">(4) Quản lý sau hợp nhất <a class="header-anchor" href="#_4-quan-ly-sau-hop-nhat" aria-label="Permalink to &quot;(4) Quản lý sau hợp nhất&quot;">​</a></h3><p>Mặc dù cá nhân sau hợp nhất giữ lại danh tính công dân của vật chủ ban đầu, nhưng cần chấp nhận quản lý đặc biệt:</p><ul><li><strong>Kiểm soát năng lượng</strong>: Việc sử dụng năng lượng bóng tối của cá nhân đã hợp nhất được kiểm soát chặt chẽ, phải thực hiện phát hiện năng lượng định kỳ, nghiêm cấm sử dụng năng lượng bóng tối ở nơi công cộng.</li><li><strong>Giám sát hành vi</strong>: Cá nhân đã hợp nhất phải báo cáo định kỳ tình trạng hành vi của mình cho Cục quản lý sự sống, chấp nhận giám sát và hỗ trợ của cộng đồng.</li><li><strong>Hạn chế tu luyện</strong>: Cá nhân đã hợp nhất không được tu luyện các pháp môn có thể làm trầm trọng thêm thuộc tính bóng tối, kế hoạch tu luyện phải được phê duyệt.</li><li><strong>Kế hoạch khẩn cấp</strong>: Xây dựng kế hoạch khẩn cấp đối với việc bóng tối của cá nhân đã hợp nhất mất kiểm soát, ngay lập tức khởi động kiểm soát khi có dấu hiệu mất kiểm soát.</li><li><strong>Cơ chế thoát ra</strong>: Nếu sau hợp nhất xuất hiện sự bất ổn nghiêm trọng hoặc hành vi nguy hiểm liên tục, có thể đánh giá lại và chuyển sang xử lý loại khác.</li></ul><h3 id="_5-xu-ly-that-bai-hop-nhat" tabindex="-1">(5) Xử lý thất bại hợp nhất <a class="header-anchor" href="#_5-xu-ly-that-bai-hop-nhat" aria-label="Permalink to &quot;(5) Xử lý thất bại hợp nhất&quot;">​</a></h3><p>Hợp nhất linh hồn có rủi ro thất bại, kế hoạch xử lý thất bại hợp nhất:</p><ul><li><strong>Gián đoạn hợp nhất</strong>: Nếu xuất hiện sự bất ổn nghiêm trọng trong quá trình hợp nhất, ngay lập tức gián đoạn hợp nhất, khôi phục hai linh hồn về trạng thái trước hợp nhất.</li><li><strong>Hợp nhất không hoàn chỉnh</strong>: Nếu sau hợp nhất xuất hiện sự không hoàn chỉnh của linh hồn hoặc phân chia nhân cách, chuyển sang xử lý loại tách đặt để xử lý tiếp theo.</li><li><strong>Hợp nhất mất kiểm soát</strong>: Nếu sau hợp nhất linh hồn mới thể hiện tính phá hủy không kiểm soát được, ngay lập tức chuyển sang xử lý loại phong ấn giám sát hoặc loại tiêu hủy.</li></ul><h2 id="_3-loai-thu-hai-xu-ly-loai-tach-đat" tabindex="-1">3. Loại thứ hai: Xử lý loại tách đặt <a class="header-anchor" href="#_3-loai-thu-hai-xu-ly-loai-tach-đat" aria-label="Permalink to &quot;3. Loại thứ hai: Xử lý loại tách đặt&quot;">​</a></h2><p>Xử lý loại tách đặt áp dụng cho các cơ thể thay thế bóng tối mà linh hồn vật chủ ban đầu và linh hồn bóng tối không thể hợp nhất nhưng có thể tách ra, thông qua phẫu thuật tách linh hồn để tách hai linh hồn, đặt riêng biệt.</p><h3 id="_1-đieu-kien-ap-dung-1" tabindex="-1">(1) Điều kiện áp dụng <a class="header-anchor" href="#_1-đieu-kien-ap-dung-1" aria-label="Permalink to &quot;(1) Điều kiện áp dụng&quot;">​</a></h3><ol><li>Cơ thể thay thế bóng tối đang ở giai đoạn ba hoặc bốn, linh hồn vật chủ ban đầu vẫn tồn tại và có khả năng phục hồi.</li><li>Nỗ lực hợp nhất của hai linh hồn đã thất bại hoặc không có điều kiện hợp nhất.</li><li>Đánh giá kỹ thuật cho rằng tách linh hồn là khả thi, sau tách linh hồn vật chủ ban đầu có thể tồn tại độc lập.</li><li>Linh hồn vật chủ ban đầu đã rõ ràng biểu đạt ý chí muốn tách ra.</li><li>Được ủy ban xét duyệt đạo đức linh hồn song sinh phê duyệt.</li></ol><h3 id="_2-muc-tieu-xu-ly-1" tabindex="-1">(2) Mục tiêu xử lý <a class="header-anchor" href="#_2-muc-tieu-xu-ly-1" aria-label="Permalink to &quot;(2) Mục tiêu xử lý&quot;">​</a></h3><p>Thông qua phẫu thuật tách linh hồn để tách linh hồn vật chủ ban đầu và linh hồn bóng tối, linh hồn vật chủ ban đầu quay trở lại cơ thể để phục hồi cuộc sống bình thường, linh hồn bóng tối được đặt trong vật chứa hoặc cơ sở đặc biệt để kiểm soát và nghiên cứu.</p><h3 id="_3-cac-buoc-xu-ly-1" tabindex="-1">(3) Các bước xử lý <a class="header-anchor" href="#_3-cac-buoc-xu-ly-1" aria-label="Permalink to &quot;(3) Các bước xử lý&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bước</th><th>Tên</th><th>Nội dung cụ thể</th><th>Cơ quan chịu trách nhiệm</th></tr></thead><tbody><tr><td>Bước một</td><td>Xét duyệt đạo đức</td><td>Ủy ban xét duyệt đạo đức linh hồn song sinh xét duyệt kế hoạch tách, xác nhận sự cần thiết và tính khả thi của việc tách</td><td>Ủy ban xét duyệt đạo đức linh hồn song sinh</td></tr><tr><td>Bước hai</td><td>Chuẩn bị tách</td><td>Thực hiện các công việc chuẩn bị trước tách như đánh giá cơ thể, phát hiện trạng thái linh hồn, điều chỉnh cân bằng năng lượng, v.v.</td><td>Đội ngũ y tế + nhà trị liệu linh hồn</td></tr><tr><td>Bước ba</td><td>Tách linh hồn</td><td>Với sự hỗ trợ của người tu luyện cấp cao và nhà trị liệu linh hồn, thực hiện phẫu thuật tách linh hồn, tách hai linh hồn ra khỏi cơ thể</td><td>Người tu luyện cấp cao + nhà trị liệu linh hồn</td></tr><tr><td>Bước bốn</td><td>Khôi phục vật chủ ban đầu</td><td>Cấy lại linh hồn vật chủ ban đầu vào cơ thể, thực hiện ổn định linh hồn và điều trị phục hồi cơ thể</td><td>Đội ngũ y tế</td></tr><tr><td>Bước năm</td><td>Đặt bóng tối</td><td>Đặt linh hồn bóng tối đã được tách vào vật chứa ngăn chặn linh hồn đặc biệt, lưu trữ tại cơ sở phong ấn linh hồn</td><td>Cục quản lý sự sống + đội ngũ kỹ thuật</td></tr><tr><td>Bước sáu</td><td>Phục hồi vật chủ ban đầu</td><td>Thực hiện phục hồi cơ thể toàn diện, điều trị tâm lý, phục hồi tu luyện cho vật chủ ban đầu, hỗ trợ quay trở lại cuộc sống bình thường</td><td>Đội ngũ y tế + cố vấn tâm lý</td></tr><tr><td>Bước bảy</td><td>Khôi phục danh tính</td><td>Xác nhận việc khôi phục hoàn toàn danh tính và quyền lợi của vật chủ ban đầu, cập nhật hồ sơ danh tính</td><td>Cơ quan quản lý đăng ký</td></tr><tr><td>Bước tám</td><td>Quản lý linh hồn bóng tối</td><td>Thực hiện giám sát liên tục và nghiên cứu đối với linh hồn bóng tối đã được tách, khám phá khả năng cải tạo hoặc tiêu hủy của nó</td><td>Cục quản lý sự sống + cơ quan nghiên cứu</td></tr></tbody></table><h3 id="_4-đat-linh-hon-bong-toi-sau-tach" tabindex="-1">(4) Đặt linh hồn bóng tối sau tách <a class="header-anchor" href="#_4-đat-linh-hon-bong-toi-sau-tach" aria-label="Permalink to &quot;(4) Đặt linh hồn bóng tối sau tách&quot;">​</a></h3><p>Linh hồn bóng tối đã được tách được đặt theo các cách sau:</p><ul><li><strong>Vật chứa linh hồn</strong>: Linh hồn bóng tối được đặt trong vật chứa ngăn chặn linh hồn đặc biệt, vật chứa được trang bị các thiết bị như khiên năng lượng, đàn áp ý thức, khóa an toàn, v.v.</li><li><strong>Cơ sở phong ấn</strong>: Vật chứa được lưu trữ trong cơ sở phong ấn linh hồn đặc biệt, cơ sở thực hiện quản lý an toàn cấp cao nhất.</li><li><strong>Giám sát liên tục</strong>: Thực hiện giám sát liên tục 24 giờ đối với hoạt động ý thức và biến động năng lượng của linh hồn bóng tối.</li><li><strong>Sử dụng nghiên cứu</strong>: Dưới sự xét duyệt đạo đức nghiêm ngặt, có thể thực hiện nghiên cứu khoa học đối với linh hồn bóng tối, khám phá bản chất của năng lượng vực thẳm và phương pháp thanh tịnh.</li><li><strong>Xử lý cuối cùng</strong>: Dựa trên kết quả nghiên cứu và đánh giá rủi ro, đưa ra quyết định xử lý cuối cùng đối với linh hồn bóng tối — cải tạo thành tồn tại không phá hủy, phong ấn dài hạn, hoặc tiêu hủy thông qua thanh tịnh.</li></ul><h3 id="_5-rui-ro-va-xu-ly-cua-viec-tach" tabindex="-1">(5) Rủi ro và xử lý của việc tách <a class="header-anchor" href="#_5-rui-ro-va-xu-ly-cua-viec-tach" aria-label="Permalink to &quot;(5) Rủi ro và xử lý của việc tách&quot;">​</a></h3><p>Phẫu thuật tách linh hồn có các rủi ro sau, phải xây dựng kế hoạch xử lý:</p><table tabindex="0"><thead><tr><th>Rủi ro</th><th>Kế hoạch xử lý</th></tr></thead><tbody><tr><td>Linh hồn vật chủ ban đầu bị tổn thương trong quá trình tách</td><td>Thực hiện tăng cường linh hồn trước tách, trong quá trình tách có người tu luyện cấp cao hỗ trợ toàn trình</td></tr><tr><td>Sau tách cơ thể vật chủ ban đầu không thể thích ứng</td><td>Sau tách thực hiện phục hồi cơ thể toàn diện và điều trị ổn định linh hồn</td></tr><tr><td>Linh hồn bóng tối trốn thoát trong quá trình tách</td><td>Việc tách được thực hiện tại cơ sở an toàn cấp cao nhất, được trang bị nhiều thiết bị ngăn chặn</td></tr><tr><td>Tách không hoàn chỉnh, năng lượng bóng tối còn sót lại</td><td>Sau tách thực hiện điều trị thanh tịnh sâu, làm sạch năng lượng bóng tối còn sót lại</td></tr><tr><td>Sau tách linh hồn vật chủ ban đầu bị sang chấn tâm lý</td><td>Cung cấp tư vấn tâm lý và điều trị tinh thần dài hạn</td></tr></tbody></table><h2 id="_4-loai-thu-ba-xu-ly-loai-phong-an-giam-sat" tabindex="-1">4. Loại thứ ba: Xử lý loại phong ấn giám sát <a class="header-anchor" href="#_4-loai-thu-ba-xu-ly-loai-phong-an-giam-sat" aria-label="Permalink to &quot;4. Loại thứ ba: Xử lý loại phong ấn giám sát&quot;">​</a></h2><p>Xử lý loại phong ấn giám sát áp dụng cho các cơ thể thay thế bóng tối không thể hợp nhất cũng không thể tách, nhưng linh hồn vật chủ ban đầu vẫn tồn tại và không có điều kiện để tiêu hủy ngay lập tức, thông qua các biện pháp phong ấn để kiểm soát tính nguy hiểm của nó, thực hiện giám sát dài hạn và đánh giá liên tục.</p><h3 id="_1-đieu-kien-ap-dung-2" tabindex="-1">(1) Điều kiện áp dụng <a class="header-anchor" href="#_1-đieu-kien-ap-dung-2" aria-label="Permalink to &quot;(1) Điều kiện áp dụng&quot;">​</a></h3><ol><li>Cơ thể thay thế bóng tối đang ở giai đoạn bốn (giai đoạn thống trị bóng tối), linh hồn vật chủ ban đầu bị đàn áp sâu sắc nhưng chưa chết.</li><li>Cả hợp nhất và tách đều không có tính khả thi kỹ thuật hoặc rủi ro quá cao.</li><li>Mức độ rủi ro của cơ thể thay thế bóng tối là cấp ba (rủi ro cao), nhưng chưa đạt đến mức độ cần tiêu hủy ngay lập tức.</li><li>Linh hồn vật chủ ban đầu vẫn có khả năng phục hồi yếu ớt, cần thời gian và điều kiện để chờ đợi cơ hội.</li><li>Ủy ban xét duyệt đạo đức linh hồn song sinh đã phê duyệt kế hoạch phong ấn.</li></ol><h3 id="_2-muc-tieu-xu-ly-2" tabindex="-1">(2) Mục tiêu xử lý <a class="header-anchor" href="#_2-muc-tieu-xu-ly-2" aria-label="Permalink to &quot;(2) Mục tiêu xử lý&quot;">​</a></h3><p>Thông qua các biện pháp phong ấn để đàn áp sức mạnh và hoạt động của linh hồn bóng tối, kiểm soát tính nguy hiểm của cơ thể thay thế bóng tối, đồng thời bảo vệ linh hồn vật chủ ban đầu không bị tiêu diệt hoàn toàn, trong quá trình giám sát dài hạn chờ đợi sự chín muồi của thời điểm phục hồi hoặc xử lý.</p><h3 id="_3-phuong-phap-phong-an" tabindex="-1">(3) Phương pháp phong ấn <a class="header-anchor" href="#_3-phuong-phap-phong-an" aria-label="Permalink to &quot;(3) Phương pháp phong ấn&quot;">​</a></h3><p>Dựa trên cấp độ sức mạnh và đặc điểm của cơ thể thay thế bóng tối, lựa chọn các phương pháp phong ấn sau:</p><table tabindex="0"><thead><tr><th>Phương pháp phong ấn</th><th>Nguyên lý</th><th>Đối tượng áp dụng</th></tr></thead><tbody><tr><td>Phong ấn năng lượng</td><td>Sử dụng trận phong ấn hoặc thiết bị phong ấn để đàn áp dòng chảy và đầu ra của năng lượng bóng tối</td><td>Cơ thể thay thế bóng tối cấp độ sức mạnh trung bình-thấp</td></tr><tr><td>Phong ấn không gian</td><td>Phong ấn cơ thể thay thế bóng tối trong không gian cô lập độc lập, cắt đứt tiếp xúc với thế giới bên ngoài</td><td>Cơ thể thay thế bóng tối cấp độ sức mạnh cao hoặc có đặc điểm lây nhiễm</td></tr><tr><td>Phong ấn ý thức</td><td>Đàn áp hoạt động ý thức của linh hồn bóng tối, giữ cho nó ở trạng thái ngủ hoặc bán ngủ</td><td>Cơ thể thay thế bóng tối có ý thức hoạt động và khả năng tấn công linh hồn</td></tr><tr><td>Phong ấn đa trọng</td><td>Sử dụng đồng thời nhiều phương pháp phong ấn, hình thành nhiều lớp bảo vệ</td><td>Cơ thể thay thế bóng tối cấp độ sức mạnh cực kỳ cao hoặc có nhiều đặc điểm nguy hiểm</td></tr><tr><td>Phong ấn neo</td><td>Sử dụng thuộc tính bản nguyên của năng lượng neo để phong ấn, là phương pháp phong ấn mạnh mẽ nhất</td><td>Cơ thể thay thế bóng tối nguy hiểm cấp vũ trụ</td></tr></tbody></table><h3 id="_4-cac-buoc-xu-ly" tabindex="-1">(4) Các bước xử lý <a class="header-anchor" href="#_4-cac-buoc-xu-ly" aria-label="Permalink to &quot;(4) Các bước xử lý&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bước</th><th>Tên</th><th>Nội dung cụ thể</th><th>Cơ quan chịu trách nhiệm</th></tr></thead><tbody><tr><td>Bước một</td><td>Xét duyệt đạo đức</td><td>Ủy ban xét duyệt đạo đức linh hồn song sinh xét duyệt kế hoạch phong ấn, xác nhận sự cần thiết và sự phù hợp của phong ấn</td><td>Ủy ban xét duyệt đạo đức linh hồn song sinh</td></tr><tr><td>Bước hai</td><td>Chuẩn bị phong ấn</td><td>Chuẩn bị trận/thiết bị/không gian phong ấn, phân bổ năng lượng và nhân sự cần thiết cho phong ấn</td><td>Đội ngũ kỹ thuật + người tu luyện cấp cao</td></tr><tr><td>Bước ba</td><td>Kiểm soát chế phục</td><td>Với sự hợp tác của đội ngũ an ninh, chế phục cơ thể thay thế bóng tối, đảm bảo không xảy ra tai nạn trong quá trình phong ấn</td><td>Bộ phận an ninh + người tu luyện cấp cao</td></tr><tr><td>Bước bốn</td><td>Thực hiện phong ấn</td><td>Thực hiện phong ấn theo kế hoạch phong ấn, đàn áp sức mạnh và hoạt động của linh hồn bóng tối</td><td>Người tu luyện cấp cao + chuyên gia phong ấn</td></tr><tr><td>Bước năm</td><td>Xác minh phong ấn</td><td>Xác minh hiệu quả và sự ổn định của phong ấn, xác nhận tính nguy hiểm của cơ thể thay thế bóng tối đã được kiểm soát</td><td>Đội ngũ kỹ thuật + đội ngũ giám sát</td></tr><tr><td>Bước sáu</td><td>Chuyển giao đặt</td><td>Chuyển giao cơ thể thay thế bóng tối đã được phong ấn đến cơ sở giám sát phong ấn đặc biệt</td><td>Bộ phận an ninh + Cục quản lý sự sống</td></tr><tr><td>Bước bảy</td><td>Giám sát liên tục</td><td>Thực hiện giám sát liên tục 24 giờ đối với trạng thái phong ấn, kiểm tra định kỳ sự ổn định của phong ấn</td><td>Đội ngũ giám sát</td></tr><tr><td>Bước tám</td><td>Đánh giá lại định kỳ</td><td>Thực hiện đánh giá lại toàn diện mỗi sáu tháng, đánh giá trạng thái linh hồn vật chủ ban đầu, đặc điểm linh hồn bóng tối, sự ổn định của phong ấn, xác định xem có khả năng điều chỉnh loại xử lý không</td><td>Đội ngũ chuyên gia nhận dạng + ủy ban xét duyệt đạo đức</td></tr><tr><td>Bước chín</td><td>Bảo trì phong ấn</td><td>Thực hiện bảo trì và tăng cường định kỳ cho phong ấn, ngăn ngừa sự suy yếu hoặc tổn thương của phong ấn</td><td>Chuyên gia phong ấn + đội ngũ kỹ thuật</td></tr></tbody></table><h3 id="_5-tieu-chuan-co-so-giam-sat-phong-an" tabindex="-1">(5) Tiêu chuẩn cơ sở giám sát phong ấn <a class="header-anchor" href="#_5-tieu-chuan-co-so-giam-sat-phong-an" aria-label="Permalink to &quot;(5) Tiêu chuẩn cơ sở giám sát phong ấn&quot;">​</a></h3><ul><li><strong>Vị trí</strong>: Cơ sở giám sát phong ấn nằm ở các vùng xa xôi có địa chất ổn định, môi trường năng lượng ổn định, dân cư thưa thớt, hoặc trong chiều không gian cô lập độc lập.</li><li><strong>Xây dựng</strong>: Cơ sở áp dụng cấu trúc bảo vệ đa trọng, bao gồm ba lớp bảo vệ: rào cản vật lý, rào cản năng lượng, khóa không gian.</li><li><strong>Thiết bị</strong>: Được trang bị thiết bị giám sát phong ấn độ chính xác cao, hệ thống tăng cường tự động, hệ thống ứng phó khẩn cấp, hệ thống năng lượng dự phòng.</li><li><strong>Nhân sự</strong>: Thực hiện hệ thống trực 24 giờ, được trang bị chuyên gia phong ấn, người giám sát, nhân viên an ninh, nhân viên xử lý khẩn cấp.</li><li><strong>Khẩn cấp</strong>: Xây dựng nhiều kế hoạch khẩn cấp như phong ấn bị tổn thương, linh hồn bóng tối trốn thoát, linh hồn vật chủ ban đầu chết, v.v., thực hiện diễn tập định kỳ.</li></ul><h3 id="_6-giai-phong-va-chuyen-đoi-phong-an" tabindex="-1">(6) Giải phóng và chuyển đổi phong ấn <a class="header-anchor" href="#_6-giai-phong-va-chuyen-đoi-phong-an" aria-label="Permalink to &quot;(6) Giải phóng và chuyển đổi phong ấn&quot;">​</a></h3><p>Trong các tình huống sau, có thể giải phóng phong ấn hoặc chuyển đổi loại xử lý:</p><ul><li><strong>Phục hồi vật chủ ban đầu</strong>: Nếu trong giai đoạn phong ấn linh hồn vật chủ ban đầu dần dần phục hồi và có điều kiện tách hoặc hợp nhất, có thể giải phóng phong ấn và chuyển sang loại tách đặt hoặc loại hợp nhất cộng sinh.</li><li><strong>Cải tạo bóng tối</strong>: Nếu trong giai đoạn phong ấn linh hồn bóng tối thể hiện khả năng cải tạo, có thể giải phóng phong ấn và thực hiện nỗ lực cải tạo trong điều kiện được kiểm soát.</li><li><strong>Phong ấn thất bại</strong>: Nếu phong ấn xuất hiện tổn thương hoặc suy yếu không thể sửa chữa, và tính nguy hiểm của cơ thể thay thế bóng tối không kiểm soát được, có thể chuyển sang xử lý loại tiêu hủy.</li><li><strong>Vật chủ ban đầu chết</strong>: Nếu trong giai đoạn phong ấn linh hồn vật chủ ban đầu chết hoàn toàn, cơ thể thay thế bóng tối trở thành tồn tại bóng tối thuần túy, có thể dựa trên tính nguy hiểm của nó chuyển sang loại tiêu hủy hoặc tiếp tục phong ấn.</li></ul><h2 id="_5-loai-thu-tu-xu-ly-loai-tieu-huy" tabindex="-1">5. Loại thứ tư: Xử lý loại tiêu hủy <a class="header-anchor" href="#_5-loai-thu-tu-xu-ly-loai-tieu-huy" aria-label="Permalink to &quot;5. Loại thứ tư: Xử lý loại tiêu hủy&quot;">​</a></h2><p>Xử lý loại tiêu hủy là phương pháp xử lý nghiêm khắc nhất trong bốn nhánh, áp dụng cho các cơ thể thay thế bóng tối không thể cứu rỗi và có tính nguy hiểm cực kỳ cao, thông qua việc tiêu diệt linh hồn bóng tối (và khi cần thiết tiêu diệt toàn bộ cơ thể) để loại bỏ mối đe dọa.</p><h3 id="_1-đieu-kien-ap-dung-3" tabindex="-1">(1) Điều kiện áp dụng <a class="header-anchor" href="#_1-đieu-kien-ap-dung-3" aria-label="Permalink to &quot;(1) Điều kiện áp dụng&quot;">​</a></h3><p>Xử lý loại tiêu hủy áp dụng cho các tình huống sau:</p><ol><li>Cơ thể thay thế bóng tối đang ở giai đoạn năm (giai đoạn thay thế hoàn toàn), linh hồn vật chủ ban đầu đã chết hoàn toàn, cơ thể hoàn toàn bị linh hồn bóng tối thống trị, trở thành tồn tại bóng tối thuần túy.</li><li>Cơ thể thay thế bóng tối đang ở giai đoạn bốn, mặc dù linh hồn vật chủ ban đầu vẫn tồn tại nhưng không thể phục hồi nữa, hợp nhất, tách, phong ấn đều không khả thi, và tính nguy hiểm của nó tiếp tục tăng lên.</li><li>Mức độ rủi ro của cơ thể thay thế bóng tối là cấp bốn (rủi ro cực cao), có tính phá hủy cấp vũ trụ, trực tiếp đe dọa sự tồn tại của văn minh, bất kỳ phương pháp xử lý nào khác cũng không thể kiểm soát mối đe dọa của nó.</li><li>Trong xử lý loại phong ấn giám sát, phong ấn thất bại và không thể phong ấn lại, tính nguy hiểm của cơ thể thay thế bóng tối không kiểm soát được.</li><li>Ủy ban xét duyệt đạo đức linh hồn song sinh đã phê duyệt kế hoạch tiêu hủy (trong tình huống khẩn cấp rủi ro cực cao có thể xử lý trước rồi bổ sung phê duyệt sau).</li></ol><h3 id="_2-nguyen-tac-tieu-huy" tabindex="-1">(2) Nguyên tắc tiêu hủy <a class="header-anchor" href="#_2-nguyen-tac-tieu-huy" aria-label="Permalink to &quot;(2) Nguyên tắc tiêu hủy&quot;">​</a></h3><p>Xử lý loại tiêu hủy liên quan đến việc tiêu diệt sự sống, phải nghiêm ngặt tuân theo các nguyên tắc sau:</p><ul><li><strong>Nguyên tắc phương tiện cuối cùng</strong>: Tiêu hủy phải là phương tiện cuối cùng khi tất cả các phương pháp xử lý khác đều không khả thi.</li><li><strong>Nguyên tắc tỷ lệ</strong>: Cường độ tiêu hủy phải phù hợp với mức độ đe dọa, nghiêm cấm sử dụng vũ lực quá mức.</li><li><strong>Nguyên tắc đau khổ tối thiểu</strong>: Tiêu hủy phải càng nhiều càng tốt áp dụng phương pháp không đau và nhanh chóng, giảm bớt đau khổ của linh hồn bóng tối (và linh hồn vật chủ ban đầu nếu vẫn tồn tại).</li><li><strong>Nguyên tắc tôn trọng vật chủ ban đầu</strong>: Nếu linh hồn vật chủ ban đầu vẫn tồn tại, trước khi tiêu hủy phải càng nhiều càng tốt giữ cho linh hồn vật chủ ban đầu tỉnh táo và có phẩm giá, khi cần thiết cho phép vật chủ ban đầu nói lời tạm biệt với bạn bè và người thân.</li><li><strong>Nguyên tắc ghi chép hoàn chỉnh</strong>: Toàn bộ quá trình tiêu hủy được ghi chép, hình thành hồ sơ hoàn chỉnh, chuẩn bị cho xét duyệt và truy vết.</li><li><strong>Nguyên tắc xét duyệt sau sự kiện</strong>: Sau khi tiêu hủy hoàn thành, thực hiện xét duyệt sau sự kiện, đánh giá sự cần thiết và sự phù hợp của tiêu hủy, tổng kết kinh nghiệm và bài học.</li></ul><h3 id="_3-phuong-phap-tieu-huy" tabindex="-1">(3) Phương pháp tiêu hủy <a class="header-anchor" href="#_3-phuong-phap-tieu-huy" aria-label="Permalink to &quot;(3) Phương pháp tiêu hủy&quot;">​</a></h3><p>Dựa trên cấp độ sức mạnh và đặc điểm của cơ thể thay thế bóng tối, lựa chọn các phương pháp tiêu hủy sau:</p><table tabindex="0"><thead><tr><th>Phương pháp tiêu hủy</th><th>Nguyên lý</th><th>Đối tượng áp dụng</th></tr></thead><tbody><tr><td>Tiêu hủy thanh tịnh ánh sáng thánh</td><td>Sử dụng năng lượng ánh sáng thánh cường độ cao để thanh tịnh linh hồn bóng tối, làm cho nó tan biến trong ánh sáng</td><td>Cơ thể thay thế bóng tối cấp độ sức mạnh trung bình-thấp</td></tr><tr><td>Thuật diệt tận linh hồn</td><td>Trực tiếp tấn công và tiêu diệt cốt lõi linh hồn của linh hồn bóng tối, làm cho nó chết hoàn toàn</td><td>Cơ thể thay thế bóng tối cấp độ sức mạnh cao</td></tr><tr><td>Tiêu hủy đuổi theo không gian</td><td>Đuổi theo cơ thể thay thế bóng tối đến hư không hoặc tận cùng thời gian, làm cho nó tan biến trong sự suy thoái không-thời gian</td><td>Cơ thể thay thế bóng tối có phòng thủ vật lý mạnh mẽ</td></tr><tr><td>Tiêu hủy bản nguyên neo</td><td>Triệu hồi năng lượng bản nguyên neo, phân hủy cơ thể thay thế bóng tối và hoàn nguyên nó về bản nguyên vũ trụ</td><td>Cơ thể thay thế bóng tối nguy hiểm cấp vũ trụ</td></tr><tr><td>Tiêu hủy liên minh mạnh者 đa chiều</td><td>Nhiều người mạnh nhất đa chiều liên minh, đàn áp và tiêu diệt cơ thể thay thế bóng tối bằng sức mạnh tuyệt đối</td><td>Cơ thể thay thế bóng tối cấp độ sức mạnh cực kỳ cao</td></tr><tr><td>Tiêu hủy cảm ứng tự hủy</td><td>Dưới sự kiểm soát nghiêm ngặt, cảm ứng tự hủy năng lượng bóng tối của cơ thể thay thế bóng tối, làm cho nó tan biến trong vụ nổ năng lượng</td><td>Cơ thể thay thế bóng tối có năng lượng không ổn định</td></tr></tbody></table><h3 id="_4-cac-buoc-xu-ly-1" tabindex="-1">(4) Các bước xử lý <a class="header-anchor" href="#_4-cac-buoc-xu-ly-1" aria-label="Permalink to &quot;(4) Các bước xử lý&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bước</th><th>Tên</th><th>Nội dung cụ thể</th><th>Cơ quan chịu trách nhiệm</th></tr></thead><tbody><tr><td>Bước một</td><td>Xét duyệt đạo đức / phê duyệt khẩn cấp</td><td>Trong tình huống thông thường ủy ban xét duyệt đạo đức linh hồn song sinh xét duyệt và phê duyệt; trong tình huống khẩn cấp rủi ro cực cao người chịu trách nhiệm cao nhất tại hiện trường ra lệnh, sau đó bổ sung phê duyệt</td><td>Ủy ban xét duyệt đạo đức linh hồn song sinh / người chịu trách nhiệm cao nhất tại hiện trường</td></tr><tr><td>Bước hai</td><td>Xây dựng kế hoạch</td><td>Xây dựng kế hoạch tiêu hủy chi tiết, bao gồm phương pháp tiêu hủy, phân bổ sức mạnh, biện pháp an toàn, kế hoạch khẩn cấp, đánh giá tác động môi trường</td><td>Bộ chỉ huy tác chiến + đội ngũ chuyên gia kỹ thuật</td></tr><tr><td>Bước ba</td><td>Tập trung sức mạnh</td><td>Tập trung người tu luyện, nhân viên kỹ thuật, thiết bị và nguồn năng lượng cần thiết để thực hiện tiêu hủy</td><td>Bộ phận an ninh + người tu luyện cấp cao</td></tr><tr><td>Bước bốn</td><td>phong tỏa khu vực</td><td>phong tỏa khu vực tiêu hủy, sơ tán nhân viên xung quanh, thiết lập tuyến cảnh báo an toàn</td><td>Bộ phận an ninh + chính quyền địa phương</td></tr><tr><td>Bước năm</td><td>Đàn áp chế phục</td><td>Đầu tiên kiểm soát hành động của cơ thể thay thế bóng tối bằng lực đàn áp, ngăn ngừa nó trốn thoát hoặc gây ra sự phá hủy lớn hơn</td><td>Người tu luyện cấp cao + lực lượng an ninh</td></tr><tr><td>Bước sáu</td><td>Thực hiện tiêu hủy</td><td>Thực hiện tiêu hủy theo kế hoạch tiêu hủy, giám sát toàn bộ quá trình, ngay lập tức khởi động kế hoạch khẩn cấp khi có dấu hiệu bất thường</td><td>Người tu luyện cấp cao + đội ngũ kỹ thuật</td></tr><tr><td>Bước bảy</td><td>Xác nhận chết</td><td>Xác nhận linh hồn bóng tối (và cơ thể) đã chết hoàn toàn, phát hiện xem có năng lượng còn sót lại hoặc mảnh vỡ linh hồn không</td><td>Đội ngũ giám sát + đội ngũ chuyên gia nhận dạng</td></tr><tr><td>Bước tám</td><td>Phục hồi môi trường</td><td>Thực hiện phục hồi môi trường cho khu vực tiêu hủy, làm sạch năng lượng bóng tối còn sót lại, phục hồi cân bằng sinh thái</td><td>Bộ phận môi trường</td></tr><tr><td>Bước chín</td><td>Xử lý sau sự kiện</td><td>Thông báo cho bạn bè và người thân của vật chủ ban đầu (nếu vật chủ ban đầu đã chết), xử lý di sản của vật chủ ban đầu, thực hiện tư vấn tâm lý</td><td>Bộ phận sự việc dân sự + cố vấn tâm lý</td></tr><tr><td>Bước mười</td><td>Lưu trữ hồ sơ và xét duyệt sau sự kiện</td><td>Lưu trữ hồ sơ ghi chép toàn bộ quá trình tiêu hủy, thực hiện xét duyệt sau sự kiện, đánh giá sự cần thiết và sự phù hợp</td><td>Cục quản lý sự sống + ủy ban xét duyệt đạo đức</td></tr></tbody></table><h3 id="_5-quy-trinh-tieu-huy-khan-cap" tabindex="-1">(5) Quy trình tiêu hủy khẩn cấp <a class="header-anchor" href="#_5-quy-trinh-tieu-huy-khan-cap" aria-label="Permalink to &quot;(5) Quy trình tiêu hủy khẩn cấp&quot;">​</a></h3><p>Đối với cơ thể thay thế bóng tối cấp bốn (rủi ro cực cao) trực tiếp đe dọa sự tồn tại của văn minh, áp dụng quy trình tiêu hủy khẩn cấp:</p><ol><li>Người chịu trách nhiệm cấp cao nhất tại hiện trường có thể trực tiếp ra lệnh khởi động tiêu hủy khẩn cấp, không cần xét duyệt đạo đức trước, nhưng phải báo cáo cho ủy ban xét duyệt đạo đức linh hồn song sinh để ghi chép trong vòng 24 giờ sau tiêu hủy.</li><li>Tiêu hủy khẩn cấp có thể sử dụng sức mạnh và nguồn năng lượng cấp cao nhất của văn minh, bao gồm triệu hồi tập trung năng lượng neo và tác chiến liên minh của người mạnh nhất đa chiều.</li><li>Mục tiêu ưu tiên của tiêu hủy khẩn cấp là loại bỏ mối đe dọa, bảo vệ sự sống và an toàn của văn minh, không theo đuổi sự &quot;thanh lịch&quot; hoặc &quot;không đau&quot; của phương pháp tiêu hủy (nhưng vẫn phải càng nhiều càng tốt giảm thiểu thiệt hại phụ thuộc).</li><li>Sau tiêu hủy khẩn cấp phải thực hiện đánh giá và phục hồi môi trường toàn diện, ngăn ngừa năng lượng bóng tối còn sót lại và thảm họa thứ cấp.</li><li>Các trường hợp tiêu hủy khẩn cấp phải trải qua xem xét lại và phân tích sâu sắc sau sự kiện, tổng kết kinh nghiệm và bài học, hoàn thiện cơ chế cảnh báo sớm và xử lý.</li></ol><h2 id="_6-co-che-chuyen-đoi-xu-ly-bon-nhanh" tabindex="-1">6. Cơ chế chuyển đổi xử lý bốn nhánh <a class="header-anchor" href="#_6-co-che-chuyen-đoi-xu-ly-bon-nhanh" aria-label="Permalink to &quot;6. Cơ chế chuyển đổi xử lý bốn nhánh&quot;">​</a></h2><p>Xử lý cơ thể thay thế bóng tối không phải là cố định, dựa trên sự thay đổi của tình huống trong quá trình xử lý, có thể thực hiện chuyển đổi giữa bốn nhánh:</p><table tabindex="0"><thead><tr><th>Hướng chuyển đổi</th><th>Điều kiện chuyển đổi</th><th>Quy trình chuyển đổi</th></tr></thead><tbody><tr><td>Hợp nhất → Tách</td><td>Nỗ lực hợp nhất thất bại hoặc sau hợp nhất xuất hiện sự bất ổn nghiêm trọng</td><td>Đánh giá lại, sau khi được phê duyệt xét duyệt đạo đức thì chuyển sang tách</td></tr><tr><td>Hợp nhất → Phong ấn</td><td>Hợp nhất thất bại và tách không khả thi, cần kiểm soát rủi ro</td><td>Đánh giá lại, sau khi được phê duyệt xét duyệt đạo đức thì chuyển sang phong ấn</td></tr><tr><td>Hợp nhất → Tiêu hủy</td><td>Hợp nhất mất kiểm soát, linh hồn mới có tính phá hủy không kiểm soát được</td><td>Đánh giá khẩn cấp, ngay lập tức chuyển sang tiêu hủy</td></tr><tr><td>Tách → Phong ấn</td><td>Tách thất bại hoặc sau tách vật chủ ban đầu không thể phục hồi, cần kiểm soát rủi ro</td><td>Đánh giá lại, sau khi được phê duyệt xét duyệt đạo đức thì chuyển sang phong ấn</td></tr><tr><td>Tách → Tiêu hủy</td><td>Trong quá trình tách linh hồn bóng tối trốn thoát và mất kiểm soát</td><td>Đánh giá khẩn cấp, ngay lập tức chuyển sang tiêu hủy</td></tr><tr><td>Phong ấn → Hợp nhất</td><td>Trong giai đoạn phong ấn linh hồn vật chủ ban đầu phục hồi, có điều kiện hợp nhất</td><td>Phát hiện trong đánh giá lại định kỳ, sau khi được phê duyệt xét duyệt đạo đức thì chuyển sang hợp nhất</td></tr><tr><td>Phong ấn → Tách</td><td>Trong giai đoạn phong ấn linh hồn vật chủ ban đầu phục hồi, có điều kiện tách</td><td>Phát hiện trong đánh giá lại định kỳ, sau khi được phê duyệt xét duyệt đạo đức thì chuyển sang tách</td></tr><tr><td>Phong ấn → Tiêu hủy</td><td>Phong ấn thất bại và không thể phong ấn lại, tính nguy hiểm không kiểm soát được</td><td>Đánh giá khẩn cấp, ngay lập tức chuyển sang tiêu hủy</td></tr><tr><td>Tiêu hủy → Khác</td><td>Tiêu hủy là phương tiện cuối cùng, một khi thực hiện thì không thể đảo ngược</td><td>Không áp dụng</td></tr></tbody></table><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Xử lý bốn nhánh của cơ thể thay thế bóng tối là kiệt tác của quản trị sự sống văn minh cộng sinh neo. Từ sự cứu rỗi tích cực của hợp nhất cộng sinh, đến sự cắt đứt chính xác của tách đặt, đến sự chờ đợi kiên nhẫn của phong ấn giám sát, cho đến phương tiện cuối cùng của loại tiêu hủy, bốn nhánh đã hình thành một quang phổ xử lý hoàn chỉnh từ nhẹ nhàng nhất đến nghiêm khắc nhất, bao gồm các tình huống có thể xảy ra khác nhau của cơ thể thay thế bóng tối. Hệ thống xử lý này không chỉ giữ vững đạo lý &quot;cứu rỗi mọi linh hồn bằng toàn lực&quot;, mà còn giữ vững đạo lý an toàn &quot;kiên quyết loại bỏ mối đe dọa không kiểm soát được&quot;, phản ánh sự cân bằng tinh tế của văn minh cộng sinh giữa đạo đức sự sống và quản trị an toàn.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>57-Nguồn gốc và bản chất của cơ thể thay thế bóng tối</li><li>58-Nguyên tắc đạo đức linh hồn song sinh</li><li>54-Quy trình xử lý ba loại sự sống kỳ lạ</li><li>48-Hệ thống tư pháp và cơ chế phán quyết</li></ul>',74)])])}const s=t(g,[["render",a]]);export{b as __pageData,s as default};
